                assignment_list = []
                for _, row in emp_df.iterrows():
                    assignment = str(row['assignment_name']).strip() if pd.notna(row['assignment_name']) else 'Unknown'
                    position = str(row['position_title']).strip() if pd.notna(row['position_title']) else 'Unknown'
                    if assignment and assignment != 'Unknown' and assignment != '':
                        assignment_list.append((assignment, position))
                if assignment_list:
                    for i, (assignment, position) in enumerate(assignment_list, 1):
                        result_lines.append(f'  {i}. Assignment: {assignment}')
                        result_lines.append(f'     Position: {position}')
                else:
                    result_lines.append('  No assignments found for this employee.')
                result_lines.append('')
                result_lines.append('-' * 60)
            result_lines.append('')
            result_lines.append(f'Total Employees with Assignments: {len(employee_names)}')
            result_lines.append('=' * 80)
            result = {'type': 'string', 'value': '\n'.join(result_lines)}
result = {'type': 'string', 'value': result.get('value', 'No data available for the requested query.')}
